/* ── flattening ────────────────────────────────────────────────────────── */

import { equatorialToeclipticJ2000 } from "@/lib/sky3d/nakshatra-stars";

export type FlatBackgroundStar = {
  /** Ecliptic longitude at J2000, degrees. */
  lon: number;
  /** Ecliptic latitude, degrees. */
  lat: number;
  mag: number;
};

let cached: FlatBackgroundStar[] | null = null;

/** Converted once and memoised at module scope — the same 2,625 points every frame, every mount. */
export function flattenBackgroundStars(): FlatBackgroundStar[] {
  if (cached) return cached;
  const out: FlatBackgroundStar[] = new Array(BACKGROUND_STAR_COUNT);
  for (let i = 0; i < BACKGROUND_STAR_COUNT; i += 1) {
    const ra = BACKGROUND_STARS[i * 3];
    const dec = BACKGROUND_STARS[i * 3 + 1];
    const mag = BACKGROUND_STARS[i * 3 + 2];
    const { lon, lat } = equatorialToeclipticJ2000(ra, dec);
    out[i] = { lon, lat, mag };
  }
  cached = out;
  return out;
}
